+.btn.primary{background:linear-gradient(180deg, rgba(201,162,39,.95), rgba(201,162,39,.82));border-color:rgba(201,162,39,.55)}
+.btn.primary:hover{background:linear-gradient(180deg, rgba(201,162,39,1), rgba(201,162,39,.86))}
+.btn.dark{background:var(--navy);color:var(--white);border-color:rgba(255,255,255,.12)}
+.btn.dark:hover{box-shadow:0 12px 26px rgba(10,22,40,.30)}
+.btn.ghost{border-color:rgba(255,255,255,.22);color:var(--white)}
+.btn.ghost:hover{background:rgba(255,255,255,.08)}
+.btn.small{padding:10px 14px;font-size:14px}
+
+.link{
+  display:inline-flex;align-items:center;gap:8px;
+  text-decoration:none;font-weight:650;color:var(--navy);
+}
+.link span{color:var(--slate-2);font-weight:600}
+.link:hover span{color:var(--navy)}
+
+/* Header + Navigation */
+.header{
+  position:sticky;top:0;z-index:50;
+  background:rgba(255,255,255,.88);
+  backdrop-filter:saturate(1.2) blur(14px);
+  border-bottom:1px solid rgba(234,236,240,.72);
+}
+.header-inner{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 0}
+.brand{display:flex;align-items:center;gap:12px;text-decoration:none}
+.brand-mark{
+  width:36px;height:36px;border-radius:12px;
+  background:radial-gradient(circle at 30% 30%, rgba(201,162,39,1), rgba(201,162,39,.2) 55%, rgba(10,22,40,1) 100%);
+  box-shadow:0 14px 26px rgba(10,22,40,.22);
+}
+.brand-name{font-weight:800;letter-spacing:.02em}
+.brand-name strong{font-family: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;letter-spacing:-0.01em}
+
+.nav{display:flex;align-items:center;gap:18px}
+.nav a{color:var(--navy);text-decoration:none;font-weight:650;font-size:14px}
+.nav a:hover{color:var(--navy-2)}
+.nav .nav-item{position:relative}
+.nav .nav-trigger{display:inline-flex;align-items:center;gap:8px}
+.nav .nav-trigger i{opacity:.7}
+
+.header-cta{display:flex;align-items:center;gap:10px}
+.hamburger{display:none;border:1px solid rgba(10,22,40,.14);background:rgba(255,255,255,.65);border-radius:12px;padding:10px 12px}
+.hamburger i{font-size:18px}
+
+/* Mega menu */
+.mega{
+  position:absolute;left:0;top:calc(100% + 12px);
+  width:min(920px, calc(100vw - 40px));
+  background:var(--white);
+  border:1px solid rgba(208,213,221,.7);
+  border-radius:18px;
+  box-shadow:var(--shadow-lg);
+  padding:18px;
+  display:none;
+}
+.mega.open{display:block}
+.mega .mega-grid{display:grid;grid-template-columns:1.35fr .85fr;gap:18px}
+.mega .mega-panel{border-radius:16px;border:1px solid rgba(234,236,240,.9);padding:16px}
+.mega .mega-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
+.mega .mega-title h4{font-size:14px;margin:0;color:var(--slate);letter-spacing:.14em;text-transform:uppercase}
+.mega .mega-list{display:grid;gap:10px}
+.mega a.mega-link{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:12px;border-radius:14px;text-decoration:none;border:1px solid rgba(234,236,240,.9)}
+.mega a.mega-link:hover{border-color:rgba(12,107,122,.25);box-shadow:0 12px 28px rgba(10,22,40,.12)}
+.mega .mega-link strong{display:block;font-size:14px}
+.mega .mega-link span{display:block;font-size:13px;color:var(--slate)}
+.mega .mega-pill{font-size:12px;font-weight:700;color:rgba(10,22,40,.72)}
+
+/* Mobile nav */
+.mobile-drawer{display:none;position:fixed;inset:0;z-index:60}
+.mobile-drawer.open{display:block}
+.mobile-backdrop{position:absolute;inset:0;background:rgba(10,22,40,.62)}
+.mobile-panel{position:absolute;top:0;right:0;height:100%;width:min(420px, 92vw);background:var(--white);box-shadow:var(--shadow-lg);padding:18px;overflow:auto}
+.mobile-panel-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
+.mobile-close{border:1px solid rgba(10,22,40,.14);background:rgba(255,255,255,.65);border-radius:12px;padding:10px 12px}
+.mobile-close i{font-size:18px}
+.mobile-nav{display:grid;gap:10px;margin-top:10px}
+.mobile-nav a{padding:12px 12px;border-radius:14px;border:1px solid var(--gray-200);text-decoration:none;font-weight:650}
+.accordion{border:1px solid var(--gray-200);border-radius:16px;overflow:hidden}
+.acc-item + .acc-item{border-top:1px solid var(--gray-200)}
+.acc-btn{width:100%;text-align:left;padding:14px 12px;background:var(--white);border:0;font-weight:750;display:flex;justify-content:space-between;align-items:center}
+.acc-btn i{opacity:.7}
+.acc-panel{display:none;padding:10px 12px 14px;background:var(--gray-50)}
+.acc-panel.open{display:grid;gap:8px}
+.acc-panel a{border:1px solid rgba(208,213,221,.65);background:var(--white)}
