+/* Hero */
+.hero{
+  padding:72px 0 64px;
+  background:
+    linear-gradient(180deg, rgba(10,22,40,.70), rgba(10,22,40,.35) 55%, rgba(10,22,40,.0) 100%),
+    url("https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=2400&q=70") center/cover no-repeat;
+  color:var(--white);
