+.banner-inner{display:flex;align-items:center;justify-content:space-between;gap:16px}
+.banner p{margin:0;color:rgba(255,255,255,.86)}
+
+/* Tabs */
+.tabs{
+  display:grid;grid-template-columns: 320px 1fr;gap:22px;
+  align-items:stretch;
+}
+.tablist{display:grid;gap:10px}
+.tab{
+  width:100%;
+  padding:14px 14px;
+  border-radius:16px;
+  border:1px solid var(--gray-200);
+  background:var(--white);
+  text-align:left;
+  display:flex;justify-content:space-between;align-items:center;
+  cursor:pointer;
+}
+.tab strong{font-size:14px}
+.tab span{font-size:13px;color:var(--slate)}
+.tab[aria-selected="true"]{border-color:rgba(201,162,39,.50);box-shadow:0 16px 36px rgba(10,22,40,.12)}
+.tabpanel{border-radius:22px;border:1px solid var(--gray-200);padding:22px;background:linear-gradient(180deg, rgba(249,250,251,1), rgba(255,255,255,1))}
+.tabpanel h3{font-size:26px;margin:0 0 8px}
+.tabpanel p{max-width:78ch}
+
+/* Insight cards */
+.insight-card{display:grid;gap:12px}
+.thumb{
+  height:160px;border-radius:16px;
+  background:linear-gradient(180deg, rgba(10,22,40,.22), rgba(10,22,40,.02)),
+    url("https://images.unsplash.com/photo-1520607162513-77705c0f0d4a?auto=format&fit=crop&w=1600&q=70") center/cover no-repeat;
+  border:1px solid rgba(234,236,240,.8);
+}
+.thumb.alt1{background-image:linear-gradient(180deg, rgba(10,22,40,.22), rgba(10,22,40,.02)), url("https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?auto=format&fit=crop&w=1600&q=70")}
+.thumb.alt2{background-image:linear-gradient(180deg, rgba(10,22,40,.22), rgba(10,22,40,.02)), url("https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=1600&q=70")}
+.insight-meta{display:flex;align-items:center;justify-content:space-between;gap:10px}
+.date{font-size:13px;color:var(--slate)}
+.insight-card h4{font-size:18px;margin:0}
+
+/* Footer */
+.footer{background:var(--navy);color:rgba(255,255,255,.86);padding:56px 0}
+.footer a{color:rgba(255,255,255,.86);text-decoration:none}
+.footer a:hover{color:var(--white)}
+.footer-grid{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr;gap:20px}
+.footer h4{margin:0 0 10px;font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.62)}
+.footer ul{list-style:none;margin:0;padding:0;display:grid;gap:10px}
+.footer .fine{margin-top:18px;padding-top:18px;border-top:1px solid rgba(255,255,255,.12);display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}
+.footer .fine small{color:rgba(255,255,255,.62)}
+
+/* Utilities */
+.muted{color:var(--slate)}
+.divider{height:1px;background:var(--gray-200)}
+.surface{background:var(--gray-50)}
+.surface-strong{background:linear-gradient(180deg, var(--gray-50), var(--white))}
+.pill-row{display:flex;gap:10px;flex-wrap:wrap}
+
+.form-row{display:flex;gap:10px;flex-wrap:wrap}
+input[type="email"], input[type="text"]{
+  padding:12px 14px;border-radius:14px;border:1px solid var(--gray-300);
+  min-width:260px;flex:1;outline:none;
+}
+input[type="email"]:focus, input[type="text"]:focus{border-color:rgba(12,107,122,.42);box-shadow:0 0 0 4px rgba(12,107,122,.12)}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero .hero-grid{grid-template-columns:1fr}
+  .tabs{grid-template-columns:1fr}
+  .grid.four{grid-template-columns:repeat(2, minmax(0, 1fr))}
+  .mega{left:auto;right:0}
+}
+
+@media (max-width: 820px){
+  .nav, .header-cta .btn.small{display:none}
+  .hamburger{display:inline-flex;align-items:center;gap:10px}
+  .footer-grid{grid-template-columns:1fr 1fr}
+  .grid.three{grid-template-columns:1fr}
+  .grid.two{grid-template-columns:1fr}
+  .hero h1{font-size:40px}
+}
+
+@media (prefers-reduced-motion: reduce){
+  .card.hover, .btn{transition:none}
+}
+
*** End Patch
PATCH

